const raw = $input.first().json;
const body = raw.body || raw;
const data = body.data || body;
const analysis = data.analysis || body.analysis || {};
const dcRaw = analysis.data_collection_results || data.data_collection || body.data_collection || {};
function dcVal(key) {
  const o = dcRaw[key];
  if (o && typeof o === 'object' && 'value' in o) return o.value;
  return dcRaw[key] ?? '';
}
let transcript = data.transcript || body.transcript || '';
if (Array.isArray(transcript)) {
  transcript = transcript.map(t => {
    if (typeof t === 'string') return t;
    return (t.role || '') + ': ' + (t.message || t.content || '');
  }).join('\n');
}
const dyn = (data.conversation_initiation_client_data || {}).dynamic_variables || {};
const leadId = String(dyn.lead_id_odoo || dcVal('lead_id_odoo') || body.lead_id_odoo || body.lead_id || '').replace(/\D/g, '') || '';
return [{
  json: {
    conversation_id: data.conversation_id || body.conversation_id || body.call_id || '',
    lead_id: leadId,
    transcript,
    call_duration_seconds: data.metadata?.call_duration_secs || data.call_duration_seconds || body.duration || 0,
    call_successful: (data.status || body.status) !== 'failed',
    data_collection: dcRaw,
    lead_name: dyn.lead_name || dcVal('lead_name') || '',
    lead_site: dyn.lead_site || dcVal('lead_site') || '',
    lead_city: dyn.lead_city || dcVal('lead_city') || '',
    current_heating: dyn.current_heating || dcVal('current_heating') || '',
    project_type: dyn.project_type || dcVal('project_type') || 'multi',
    phone: dyn.phone || dcVal('phone') || ''
  }
}];

const p = $('Parser payload EL').first().json;
const apiKey = '{{ANTHROPIC_API_KEY}}';
const prompt = `Tu es expert qualification leads rénovation énergétique Québec (thermopompes, isolation, portes/fenêtres, subventions LogisVert/Rénoclimat). Analyse et retourne UNIQUEMENT un JSON valide sans markdown.\n\nLead:\n- Nom: ${p.lead_name}\n- Ville: ${p.lead_city}\n- Site: ${p.lead_site}\n- Projet: ${p.project_type}\n- Chauffage actuel: ${p.current_heating}\n- Durée appel: ${p.call_duration_seconds}s\n- Transcript (extrait): ${(p.transcript || '').slice(0, 2000)}\n\nHOT: projet < 3 mois, propriétaire, budget confirmé, veut soumission/visite.\nWARM: intéressé, timing flexible.\nCOLD: curieux, pas de budget, locataire.\n\nRéponds: {"score":"hot|warm|cold","score_numeric":0-100,"transfer_now":true|false,"programmes_eligibles":["logisvert","renoclimat"],"subvention_estimee":0,"summary":"2 phrases","next_action":"...","odoo_stage":"Qualifié|En développement|Nouveau"}`;
let parsed = { score: 'warm', score_numeric: 50, transfer_now: false, summary: '', next_action: '', odoo_stage: 'En développement', programmes_eligibles: [], subvention_estimee: 0 };
if (!apiKey || apiKey.startsWith('{{')) {
  const dur = parseInt(p.call_duration_seconds || 0, 10);
  if (dur < 15) parsed = { ...parsed, score: 'cold', score_numeric: 20, odoo_stage: 'Nouveau' };
  return [{ json: { ...p, ...parsed } }];
}
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
    body: { model: 'claude-sonnet-4-20250514', max_tokens: 500, messages: [{ role: 'user', content: prompt }] },
    json: true,
  });
  let text = (res.content && res.content[0] && res.content[0].text) || '';
  const match = text.match(/\{[\s\S]*\}/);
  if (match) parsed = { ...parsed, ...JSON.parse(match[0]) };
} catch (e) {
  parsed.summary = 'Scoring fallback: ' + String(e.message || e);
}
return [{ json: { ...p, ...parsed } }];

const j = $input.first().json;
const token = '{{ENERGIE_WEBHOOK_TOKEN}}';
const progs = Array.isArray(j.programmes_eligibles) ? j.programmes_eligibles.join(',') : (j.programmes_eligibles || '');
const body = {
  lead_id: parseInt(j.lead_id, 10),
  score: j.score,
  score_numeric: j.score_numeric,
  transfer_now: true,
  summary: j.summary,
  next_action: j.next_action,
  conversation_id: j.conversation_id,
  transcript: j.transcript,
  programmes_eligibles: progs,
  subvention_estimee: j.subvention_estimee || 0,
  increment_call_attempt: true,
  nurture_active: false
};
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/energie/lead/update',
  headers: { 'X-Energie-Webhook-Token': token, 'Content-Type': 'application/json' },
  body,
  json: true,
});
return [{ json: { ...j, odoo: res } }];

const j = $input.first().json;
const token = '{{ENERGIE_WEBHOOK_TOKEN}}';
const progs = Array.isArray(j.programmes_eligibles) ? j.programmes_eligibles.join(',') : (j.programmes_eligibles || '');
const body = {
  lead_id: parseInt(j.lead_id, 10),
  score: j.score,
  score_numeric: j.score_numeric,
  transfer_now: false,
  summary: j.summary,
  next_action: j.next_action,
  conversation_id: j.conversation_id,
  transcript: j.transcript,
  programmes_eligibles: progs,
  subvention_estimee: j.subvention_estimee || 0,
  increment_call_attempt: true,
  nurture_active: true
};
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/energie/lead/update',
  headers: { 'X-Energie-Webhook-Token': token, 'Content-Type': 'application/json' },
  body,
  json: true,
});
return [{ json: { ...j, odoo: res } }];

const j = $('Claude Scoring').first().json;
const phone = j.phone || '';
if (!phone || j.score !== 'hot') return [{ json: j }];
const sid = '{{TWILIO_ACCOUNT_SID}}';
const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
const from = '{{TWILIO_FROM_ENERGIE}}';
const first = (j.lead_name || '').split(' ')[0] || 'Bonjour';
const site = j.lead_site || 'Énergie Pro';
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent(from)}&Body=${encodeURIComponent(first + ', merci pour votre appel ' + site + '! Un conseiller Énergie Pro vous contacte sous peu pour votre soumission gratuite.')}`,
});
return [{ json: j }];

const j = $('Claude Scoring').first().json;
const phone = j.phone || '';
if (!phone || j.score === 'hot') return [{ json: j }];
const sid = '{{TWILIO_ACCOUNT_SID}}';
const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
const from = '{{TWILIO_FROM_ENERGIE}}';
const first = (j.lead_name || '').split(' ')[0] || 'Bonjour';
const sub = j.subvention_estimee ? ` Estimation subventions: ~${j.subvention_estimee}$.` : '';
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent(from)}&Body=${encodeURIComponent(first + ' — Énergie Pro: on prépare votre dossier subventions (LogisVert/Rénoclimat).' + sub + ' Répondez OUI pour fixer un rappel.')}`,
});
return [{ json: j }];
